//! C ABI for embedding the simulator in C and C++ trainers; the header is generated by cbindgen.

use std::ffi::{CStr, c_char};

const VERSION: &CStr =
    match CStr::from_bytes_with_nul(concat!(env!("CARGO_PKG_VERSION"), "\0").as_bytes()) {
        Ok(version) => version,
        Err(_) => panic!("crate version contains a NUL byte"),
    };

#[must_use]
pub fn version() -> &'static CStr {
    VERSION
}

/// Returns the library version as a static NUL-terminated string owned by the library.
#[allow(
    unsafe_code,
    reason = "no_mangle is required to export a stable C symbol"
)]
#[unsafe(no_mangle)]
pub extern "C" fn ksim_version() -> *const c_char {
    VERSION.as_ptr()
}
